                            raise ValueError(
                                "conv1d_batch intermediate must be finite"
                            )
                        acc = acc + product
                        if not math.isfinite(acc):
                            raise ValueError(
                                "conv1d_batch intermediate must be finite"
                            )
                out_data[oi] = acc
    needs_grad = self.requires_grad or kernel.requires_grad
    if bias is not None and bias.requires_grad:
        needs_grad = True
    if not needs_grad:
